/**
 * TypeScript Template Node for Node-RED
 * Template node with TypeScript interface validation and IntelliSense
 */

module.exports = function(RED) {
    "use strict";
    var mustache = require("mustache");
    var vm = require("vm");
    var path = require("path");
    var fs = require("fs-extra");
    
    // Import TypeScript compiler service
    var TypeScriptCompiler = require("../../../runtime/lib/typescript-compiler");

    function TypeScriptTemplateNode(n) {
        RED.nodes.createNode(this, n);
        var node = this;
        
        node.name = n.name;
        node.template = n.template;
        node.interfaceImport = n.interfaceImport; // e.g., "@userDir/lib/types"
        node.interfaceName = n.interfaceName; // e.g., "UserProfileData" 
        node.compiledValidation = n.compiledValidation; // Compiled validation function
        node.validationErrors = n.validationErrors || [];
        node.outputFormat = n.outputFormat || "str"; // str, json, yaml
        
        var validatePayload = null;
        
        // Set up validation if available
        if (node.compiledValidation && node.validationErrors.length === 0) {
            try {
                var sandbox = {
                    require: require,
                    console: console,
                    exports: {},
                    module: { exports: {} },
                    Buffer: Buffer,
                    Date: Date,
                    JSON: JSON,
                    Object: Object,
                    Array: Array
                };
                
                vm.runInNewContext(node.compiledValidation, sandbox);
                validatePayload = sandbox.module.exports;
                
                node.status({
                    fill: "green", 
                    shape: "dot", 
                    text: `Ready (${node.interfaceName})`
                });
                
                console.log(`[TS-Template] Validation function loaded for ${node.interfaceName}`);
                
            } catch (err) {
                console.error('[TS-Template] Failed to load validation function:', err);
                node.error("Failed to load validation function: " + err.message);
                node.status({fill: "red", shape: "ring", text: "Validation load error"});
            }
        } else if (node.validationErrors.length > 0) {
            node.status({fill: "red", shape: "ring", text: "Interface errors"});
            node.error("Interface compilation errors: " + node.validationErrors.map(e => e.message).join(', '));
        } else {
            node.status({fill: "yellow", shape: "ring", text: "No validation"});
        }

        node.on("input", function(msg, send, done) {
            try {
                console.log('[TS-Template] Processing message with payload type:', typeof msg.payload);
                
                // Runtime type validation
                if (validatePayload) {
                    console.log('[TS-Template] Validating payload against', node.interfaceName);
                    var validationResult = validatePayload(msg.payload);
                    
                    if (!validationResult.valid) {
                        var errorMsg = `Payload validation failed for ${node.interfaceName}:\n` + 
                                     validationResult.errors.join('\n');
                        console.error('[TS-Template] Validation failed:', validationResult.errors);
                        node.error(errorMsg, msg);
                        if (done) done(new Error("Type validation failed"));
                        return;
                    }
                    
                    // Add type metadata
                    msg._templateType = node.interfaceName;
                    msg._templateValidated = true;
                    
                    console.log(`[TS-Template] ✅ Payload validated against ${node.interfaceName}`);
                }
                
                // Render template with Mustache
                console.log('[TS-Template] Rendering template...');
                var rendered = mustache.render(node.template, msg.payload);
                
                // Handle output format
                if (node.outputFormat === "json") {
                    try {
                        rendered = JSON.parse(rendered);
                    } catch (e) {
                        node.warn("Template output is not valid JSON, keeping as string");
                    }
                } else if (node.outputFormat === "yaml") {
                    try {
                        var yaml = require("js-yaml");
                        rendered = yaml.load(rendered);
                    } catch (e) {
                        node.warn("Template output is not valid YAML, keeping as string");
                    }
                }
                
                msg.payload = rendered;
                
                console.log('[TS-Template] Template rendered successfully');
                send(msg);
                if (done) done();
                
            } catch (err) {
                console.error('[TS-Template] Template processing error:', err);
                node.error("Template processing error: " + err.message, msg);
                if (done) done(err);
            }
        });
        
        node.on("close", function() {
            node.status({});
        });
    }
    
    RED.nodes.registerType("typescript-template", TypeScriptTemplateNode);
    
    // Add HTTP endpoint to get interface details for IntelliSense
    RED.httpAdmin.get("/typescript-template/interface-info", function(req, res) {
        const interfaceImport = req.query.import;
        const interfaceName = req.query.name;
        
        if (!interfaceImport || !interfaceName) {
            return res.status(400).json({ error: "Missing import or name parameter" });
        }
        
        try {
            console.log(`[TS-Template] Getting interface info for ${interfaceName} from ${interfaceImport}`);
            
            // This would extract interface details for IntelliSense
            // For now, return a basic structure
            res.json({
                interfaceName: interfaceName,
                interfaceImport: interfaceImport,
                properties: [], // This would be populated by parsing the TypeScript interface
                success: true
            });
            
        } catch (error) {
            console.error('[TS-Template] Error getting interface info:', error);
            res.status(500).json({ error: error.message });
        }
    });
    
    // Add HTTP endpoint to compile template validation
    RED.httpAdmin.post("/typescript-template/compile-validation", function(req, res) {
        const { interfaceImport, interfaceName } = req.body;
        
        if (!interfaceImport || !interfaceName) {
            return res.status(400).json({ error: "Missing interfaceImport or interfaceName" });
        }
        
        try {
            console.log(`[TS-Template] Compiling validation for ${interfaceName} from ${interfaceImport}`);
            
            // Generate validation TypeScript code
            const validationCode = `
import { ${interfaceName} } from '${interfaceImport}';

// Type guard functions
function isObject(obj: any): obj is Record<string, any> {
    return obj !== null && typeof obj === 'object' && !Array.isArray(obj);
}

function isString(value: any): value is string {
    return typeof value === 'string';
}

function isNumber(value: any): value is number {
    return typeof value === 'number' && !isNaN(value);
}

function isBoolean(value: any): value is boolean {
    return typeof value === 'boolean';
}

function isArray(value: any): value is any[] {
    return Array.isArray(value);
}

function isDate(value: any): value is Date {
    return value instanceof Date && !isNaN(value.getTime());
}

// Enhanced validation function with detailed error reporting
function validatePayload(data: any): { valid: boolean; errors: string[] } {
    const errors: string[] = [];
    
    try {
        console.log('[TS-Template-Validator] Validating payload against ${interfaceName}');
        
        // Basic type check
        if (data === null || data === undefined) {
            errors.push('Payload is null or undefined');
            return { valid: false, errors };
        }
        
        if (!isObject(data)) {
            errors.push(\`Expected object for ${interfaceName}, got \${typeof data}\`);
            return { valid: false, errors };
        }
        
        // Runtime validation against TypeScript interface
        // This is a simplified validation - in a full implementation you'd want
        // to generate specific validation logic based on the interface structure
        const result = validateAgainstInterface(data, '');
        
        console.log('[TS-Template-Validator] Validation result:', result.valid ? 'PASS' : 'FAIL');
        if (!result.valid) {
            console.log('[TS-Template-Validator] Validation errors:', result.errors);
        }
        
        return result;
        
    } catch (error) {
        console.error('[TS-Template-Validator] Validation error:', error);
        errors.push(\`Validation error: \${error.message}\`);
        return { valid: false, errors };
    }
}

// Interface-specific validation function
function validateAgainstInterface(obj: any, path: string): { valid: boolean; errors: string[] } {
    const errors: string[] = [];
    const currentPath = path || 'root';
    
    try {
        // Type assertion for compile-time checking
        const typedObj = obj as ${interfaceName};
        
        // The TypeScript compiler will catch structural mismatches at compile time
        // At runtime, we do basic existence and type checks
        
        // This validation function acts as a bridge between compile-time and runtime
        console.log(\`[TS-Template-Validator] Validating object at path: \${currentPath}\`);
        
        // Basic validation - object exists and is the right basic type
        if (!isObject(obj)) {
            errors.push(\`\${currentPath}: Expected object, got \${typeof obj}\`);
        }
        
        // Additional runtime checks would go here based on the specific interface
        // For now, we rely on TypeScript's compile-time checking
        
        return { valid: errors.length === 0, errors };
        
    } catch (error) {
        errors.push(\`\${currentPath}: Validation error - \${error.message}\`);
        return { valid: false, errors };
    }
}

// Export the validation function
module.exports = validatePayload;
`;
            
            // Use the existing TypeScript compiler
            const userDir = RED.settings.userDir || process.env.NODE_RED_HOME || '.';
            const compiler = new TypeScriptCompiler(userDir);
            
            compiler.compileCode(validationCode, (err, result) => {
                if (err) {
                    console.error('[TS-Template] Validation compilation failed:', err);
                    return res.status(500).json({ 
                        success: false, 
                        error: err.message,
                        errors: [{ message: err.message, line: 0, column: 0 }]
                    });
                }
                
                if (result.errors && result.errors.length > 0) {
                    console.error('[TS-Template] Validation compilation errors:', result.errors);
                    return res.json({
                        success: false,
                        errors: result.errors,
                        outputText: ""
                    });
                }
                
                console.log('[TS-Template] ✅ Validation compiled successfully');
                res.json({
                    success: true,
                    errors: [],
                    outputText: result.outputText
                });
            });
            
        } catch (error) {
            console.error('[TS-Template] Compilation error:', error);
            res.status(500).json({ error: error.message });
        }
    });
}; 